```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate
WHERE {
  VALUES ?film { dbr:Going_All_the_Way dbr:Married_to_the_Mob }

  # director (prefer dbo:director, fallback to dbp:director)
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?film dbp:director ?director . }

  # film label (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?film dbp:name ?filmLabel . }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }

  # director label (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?director dbp:name ?directorLabel . }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }

  # director birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDateDBP . }
  OPTIONAL { ?director dbo:birthDate ?birthDateDBO . }
  BIND (COALESCE(?birthDateDBP, ?birthDateDBO) AS ?birthDate)
}
LIMIT 100
